        {"from": "m40_xiejin", "to": "m40_yaoguangxiao", "role": "《永乐大典》初修主持者与共同修书者", "inverse": "扩大重修阶段的监修者与共同修书者", "period": "1403—1408", "note": "大典由众多官员、学者和书手完成，不能归为两人私著。", "sources": ["v40m1_ms147", "v40m1_ms145", "v12_dpm_yongle"]},
